        raise ValueError(f"invalid date {cell!r}") from None


def _parse_nova_date(cell: str) -> dt.date:
    try:
        return dt.date.fromisoformat(cell.strip())
    except ValueError:
        raise ValueError(f"invalid date {cell!r}") from None


def _parse_sfera_amount(cell: str, *, signed: bool):
